using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpHttpServer;

/// <summary>
/// Exposes application configuration data as an MCP resource.
/// </summary>
public class ConfigResourceHandler : ResourceHandler
{
    public override ResourceTemplate Template { get; } = new()
    {
        UriTemplate = "config://app/{section}",
        Name = "Application Configuration",
        Description = "Returns configuration data for a given section (e.g. 'database', 'logging').",
        MimeType = "application/json",
    };

    protected override Task<ReadResourceResult> ReadResourceAsync(
        RequestContext<ReadResourceRequestParams> request,
        CancellationToken cancellationToken)
    {
        var uri = request.Params!.Uri;
        var section = uri.Replace("config://app/", "", StringComparison.OrdinalIgnoreCase);

        var data = section.ToLowerInvariant() switch
        {
            "database" => new Dictionary<string, object>
            {
                ["host"] = "db.example.com",
                ["port"] = 5432,
                ["name"] = "app_production",
                ["maxConnections"] = 20,
            },
            "logging" => new Dictionary<string, object>
            {
                ["level"] = "Information",
                ["format"] = "json",
                ["retentionDays"] = 30,
            },
            "feature-flags" => new Dictionary<string, object>
            {
                ["darkMode"] = true,
                ["betaFeatures"] = false,
                ["maxUploadSizeMb"] = 50,
            },
            _ => new Dictionary<string, object>
            {
                ["error"] = $"Unknown section: {section}",
            },
        };

        return Task.FromResult(new ReadResourceResult
        {
            Contents =
            [
                new ResourceContents
                {
                    Uri = uri,
                    MimeType = "application/json",
                    Text = JsonSerializer.Serialize(data, new JsonSerializerOptions
                    {
                        WriteIndented = true,
                    }),
                }
            ],
        });
    }
}

