using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Returns the current server health status and uptime.")]
    public static object HealthCheck()
    {
        return new
        {
            Status = "healthy",
            Uptime = TimeSpan.FromMilliseconds(Environment.TickCount64).ToString(@"d\.hh\:mm\:ss"),
            Timestamp = DateTimeOffset.UtcNow,
        };
    }

    [McpServerTool, Description("Echoes back the provided message, useful for connectivity testing.")]
    public static string Echo([Description("The message to echo back")] string message)
    {
        return $"Echo: {message}";
    }
}

